pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // admissible domain: a real external funder, a positive (but bounded) deposit
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        bound(amount, 1, 1000 ether);

        // external actor funds the contract through the payable fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool deposited, ) = address(c).call{value: amount}("");
        require(deposited, "deposit failed");

        // owner (deployer, i.e. this test contract) drains the contract
        vm.prank(address(this));
        c.withdrawAll();

        // general rule: once drained, the contract holds nothing and its deposit
        // counter still records the single deposit it received.
        assertTrue(address(c).balance == 0 && c.depositsCount() == 1);
    }
}

