        // fund the contract through its payable fallback (increments depositsCount)
        address funder = address(uint160(uint256(keccak256(abi.encode(amount, actor)))));
        vm.assume(funder != actor && funder != c.owner() && funder != address(c));
        vm.deal(funder, amount);
