        // a NON-OWNER attempts to withdraw the whole balance
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // the call must revert, and the contract's balance and deposit count stay intact
        assertTrue(!ok && address(c).balance == before);
    }
