pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address attacker) public {
        // keep domain wide: any positive funding, any caller except the
        // owner (this test contract) and the zero address (prank(0) is a no-op)
        vm.assume(amount > 0);
        vm.assume(attacker != address(0));
        vm.assume(attacker != address(this));
        vm.assume(attacker != address(c));

        // fund the contract with a fuzzer-chosen amount via the payable fallback
        vm.deal(address(this), amount);
        (bool dep, ) = address(c).call{value: amount}("");
        assertTrue(dep, "deposit via fallback must succeed");
        assertTrue(address(c).balance == amount, "contract holds the deposit");

        // a NON-OWNER calls withdrawAll; in the reference this must revert
        vm.prank(attacker);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // Universal rule: no caller other than the owner can successfully
        // withdrawAll (and thereby empty the contract). The mutant removes
        // onlyOwner, letting the attacker drain the full balance.
        assertTrue(!ok && address(c).balance == amount, "non-owner must not be able to withdrawAll");
    }
}

