pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seedDeposit, uint256 amount, address actor) public {
        seedDeposit = bound(seedDeposit, 0, 1e30);
        amount = bound(amount, 1, seedDeposit);
        vm.assume(actor != address(0));
        address owner = c.owner();
        vm.deal(address(this), seedDeposit);
        (bool s, ) = address(c).call{value: seedDeposit}("");
        assertTrue(s);
        vm.prank(actor);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", amount));
        assertTrue(ok);
        vm.prank(actor);
        c.depositsCount();
        // Rule: withdraw(amount) as non-owner reverts or, if owner, leaves balance - amount;
        // drive as owner to observe exact decrement:
        vm.prank(owner);
        c.withdraw(amount);
        assertTrue(address(c).balance == seedDeposit - amount,
            "withdraw(v) must leave balance - v");
    }
    receive() external payable {}
}

